out=[]
for ref,(title,links,note) in H.items():
  r=get(ref); assert r, ref
  h=r[0]
  g=h['grade'] or ''
  if ref.startswith(('B:','M:')): g='Sahih'
  out.append(dict(id=ref.replace(':','-'),title=title,ref=h['ref'].replace('Jami` at-Tirmidhi','Jami at-Tirmidhi'),grade=g,narrator=h['pre'].strip(),en=(h['en']+(' '+h['post'] if h['post'] else '')).strip(),ar=h['ar'].strip(),note=note,links=[{'s':s,'v':v} for s,v in links]))
json.dump(out,open('hadith.json','w'),ensure_ascii=False)
print(len(out), sum(len(x['en']) for x in out)//1000,'k chars EN', sum(len(x['ar']) for x in out)//1000,'k AR')
print(set(x['grade'] for x in out)); print([x['ref'] for x in out if not x['ar']])
